dashboard.definition:
{
  "title": "Token Usage",
  "description": "Token mix deep dive across models and sessions",
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "inputs": {
    "input_timerange": {
      "type": "input.timerange",
      "options": {
        "token": "global_time",
        "defaultValue": "-7d@d,now"
      },
      "title": "Time Range"
    },
    "input_model": {
      "type": "input.dropdown",
      "title": "Model",
      "dataSources": {
        "primary": "ds_model_options"
      },
      "options": {
        "defaultValue": "*",
        "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
        "token": "model_tok"
      },
      "context": {
        "formattedConfig": {
          "number": {
            "prefix": ""
          }
        },
        "formattedStatics": ">statics | formatByType(formattedConfig)",
        "statics": [
          ["All"],
          ["*"]
        ],
        "label": ">primary | seriesByName(\"model\") | renameSeries(\"label\") | formatByType(formattedConfig)",
        "value": ">primary | seriesByName(\"model\") | renameSeries(\"value\") | formatByType(formattedConfig)"
      }
    }
  },
  "dataSources": {
    "ds_model_options": {
      "type": "ds.search",
      "options": {
        "query": "`claude_metric_events` | stats count by model | sort - count | fields model"
      },
      "name": "Model Options"
    },
    "ds_base_time": {
      "type": "ds.search",
      "options": {
        "query": "`claude_metric_events` | search model=$model_tok|s$ | timechart sum(input_tokens) as \"Input\", sum(output_tokens) as \"Output\", sum(cache_read_tokens) as \"Cache Read\", sum(cache_creation_tokens) as \"Cache Created\""
      },
      "name": "Base: Tokens Over Time"
    },
    "ds_kpi_input": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_time",
        "query": "| stats sum(\"Input\") as count | eval count=tostring(count,\"commas\") | fields count"
      },
      "name": "KPI Input Tokens"
    },
    "ds_kpi_output": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_time",
        "query": "| stats sum(\"Output\") as count | eval count=tostring(count,\"commas\") | fields count"
      },
      "name": "KPI Output Tokens"
    },
    "ds_kpi_cache_read": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_time",
        "query": "| stats sum(\"Cache Read\") as count | eval count=tostring(count,\"commas\") | fields count"
      },
      "name": "KPI Cache Read"
    },
    "ds_kpi_cache_created": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_time",
        "query": "| stats sum(\"Cache Created\") as count | eval count=tostring(count,\"commas\") | fields count"
      },
      "name": "KPI Cache Created"
    },
    "ds_kpi_ratio": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_time",
        "query": "| stats sum(\"Output\") as o, sum(\"Input\") as i | eval count=if(i>0, round(o/i,2), \"n/a\") | fields count"
      },
      "name": "KPI Output/Input Ratio"
    },
    "ds_efficiency": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_time",
        "query": "| eval \"Output/Input Ratio\"=if('Input'>0, round('Output'/'Input',3), null()) | fields _time, \"Output/Input Ratio\""
      },
      "name": "Output/Input Ratio Over Time"
    },
    "ds_base_model": {
      "type": "ds.search",
      "options": {
        "query": "`claude_metric_events` | search model=$model_tok|s$ | stats sum(input_tokens) as input, sum(output_tokens) as output, sum(cache_read_tokens) as cache_read, sum(cache_creation_tokens) as cache_created, sum(total_tokens) as total by model"
      },
      "name": "Base: Tokens by Model"
    },
    "ds_model_bar": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_model",
        "query": "| sort - total | head 10 | fields model, total | rename model as \"Model\", total as \"Total Tokens\""
      },
      "name": "Top Models by Tokens"
    },
    "ds_model_mix": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_model",
        "query": "| sort - total | head 10 | fields model, input, output, cache_read, cache_created | rename model as \"Model\", input as \"Input\", output as \"Output\", cache_read as \"Cache Read\", cache_created as \"Cache Created\""
      },
      "name": "Token Mix by Model"
    },
    "ds_base_session": {
      "type": "ds.search",
      "options": {
        "query": "`claude_metric_events` | search model=$model_tok|s$ | stats sum(total_tokens) as tokens, sum(input_tokens) as input, sum(output_tokens) as output, count as messages by sessionId"
      },
      "name": "Base: Tokens by Session"
    },
    "ds_session_table": {
      "type": "ds.chain",
      "options": {
        "extend": "ds_base_session",
        "query": "| sort - tokens | head 20 | rename sessionId as \"Session ID\", tokens as \"Total Tokens\", input as \"Input\", output as \"Output\", messages as \"Messages\""
      },
      "name": "Top Sessions by Tokens"
    }
  },
  "visualizations": {
    "viz_kpi_input": {
      "type": "splunk.singlevalue",
      "title": "Input Tokens",
      "dataSources": {
        "primary": "ds_kpi_input"
      },
      "options": {
        "majorValue": "> primary | seriesByIndex(0)"
      }
    },
    "viz_kpi_output": {
      "type": "splunk.singlevalue",
      "title": "Output Tokens",
      "dataSources": {
        "primary": "ds_kpi_output"
      },
      "options": {
        "majorValue": "> primary | seriesByIndex(0)"
      }
    },
    "viz_kpi_cache_read": {
      "type": "splunk.singlevalue",
      "title": "Cache Read",
      "dataSources": {
        "primary": "ds_kpi_cache_read"
      },
      "options": {
        "majorValue": "> primary | seriesByIndex(0)"
      }
    },
    "viz_kpi_cache_created": {
      "type": "splunk.singlevalue",
      "title": "Cache Created",
      "dataSources": {
        "primary": "ds_kpi_cache_created"
      },
      "options": {
        "majorValue": "> primary | seriesByIndex(0)"
      }
    },
    "viz_kpi_ratio": {
      "type": "splunk.singlevalue",
      "title": "Output/Input Ratio",
      "dataSources": {
        "primary": "ds_kpi_ratio"
      },
      "options": {
        "majorValue": "> primary | seriesByIndex(0)"
      }
    },
    "viz_token_breakdown": {
      "type": "splunk.area",
      "title": "Token Breakdown Over Time",
      "dataSources": {
        "primary": "ds_base_time"
      },
      "options": {
        "stackMode": "stacked"
      }
    },
    "viz_efficiency": {
      "type": "splunk.line",
      "title": "Output/Input Ratio Over Time",
      "dataSources": {
        "primary": "ds_efficiency"
      },
      "options": {}
    },
    "viz_model_bar": {
      "type": "splunk.bar",
      "title": "Top Models by Tokens",
      "dataSources": {
        "primary": "ds_model_bar"
      },
      "options": {}
    },
    "viz_model_mix": {
      "type": "splunk.column",
      "title": "Token Mix by Model",
      "dataSources": {
        "primary": "ds_model_mix"
      },
      "options": {
        "stackMode": "stacked"
      }
    },
    "viz_session_table": {
      "type": "splunk.table",
      "title": "Top Sessions by Tokens",
      "dataSources": {
        "primary": "ds_session_table"
      },
      "options": {},
      "eventHandlers": [
        {
          "type": "drilldown.linkToDashboard",
          "options": {
            "app": "VisiCore_App_for_AI_Observability",
            "dashboard": "sessions",
            "tokens": [
              {
                "token": "form.session_tok",
                "value": "row.Session ID.value"
              }
            ]
          }
        }
      ]
    }
  },
  "layout": {
    "type": "grid",
    "options": {},
    "structure": [
      {"item": "viz_kpi_input", "type": "block", "position": {"x": 0, "y": 0, "w": 240, "h": 120}},
      {"item": "viz_kpi_output", "type": "block", "position": {"x": 240, "y": 0, "w": 240, "h": 120}},
      {"item": "viz_kpi_cache_read", "type": "block", "position": {"x": 480, "y": 0, "w": 240, "h": 120}},
      {"item": "viz_kpi_cache_created", "type": "block", "position": {"x": 720, "y": 0, "w": 240, "h": 120}},
      {"item": "viz_kpi_ratio", "type": "block", "position": {"x": 960, "y": 0, "w": 240, "h": 120}},
      {"item": "viz_token_breakdown", "type": "block", "position": {"x": 0, "y": 120, "w": 600, "h": 300}},
      {"item": "viz_efficiency", "type": "block", "position": {"x": 600, "y": 120, "w": 600, "h": 300}},
      {"item": "viz_model_bar", "type": "block", "position": {"x": 0, "y": 420, "w": 600, "h": 300}},
      {"item": "viz_model_mix", "type": "block", "position": {"x": 600, "y": 420, "w": 600, "h": 300}},
      {"item": "viz_session_table", "type": "block", "position": {"x": 0, "y": 720, "w": 1200, "h": 320}}
    ],
    "globalInputs": ["input_timerange", "input_model"]
  }
}
